## ----comparison-functions, include=FALSE--------------------------------------
comparison_methods <- c("OLS", "Ridge", "NS", "FBayes", "SBayes")

calc_coef_sse <- function(Acoef1, Acoef2) {
  sum(vapply(seq_along(Acoef1), function(i) {
    sum((Acoef1[[i]] - Acoef2[[i]])^2)
  }, numeric(1)))
}

calc_forecast_msfe <- function(fit, Y_test) {
  Y_test <- as.matrix(Y_test)
  fcst <- predict(fit, n.ahead = nrow(Y_test))$fcst
  Y_hat <- sapply(colnames(Y_test), function(v) fcst[[v]][, "fcst"])
  mean((Y_hat - Y_test)^2)
}


