        ylab = "Average time (sec)", xlab = "T",
        ylim = c(min(average_time, na.rm = TRUE),
                 max(average_time, na.rm = TRUE)),
        main = "")
legend("top", inset = c(0.0, -0.2), rownames(average_time),
       ncol = 5, pch = line_id, col = line_id, lwd = 2, lty = line_id,
       cex = 0.8)
